var t=`0265-crni-rizot`;var n=`world-0265`;var a=`HR`;var o=`southern-europe`;var s=4;var r=45;var g={en:`Crni Rižot`,ua:`Чорне ризото`};var l={en:`An approximation of Dalmatian black risotto using black rice with squid; real crni rižot needs squid ink, absent from the catalog.`,ua:`Наближений варіант далматинського чорного ризото з чорним рисом і кальмаром; для справжнього крні-ріжоту потрібне чорнило каракатиці, якого немає в каталозі.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`squid`,560,`g`],[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,50,`ml`],[`tomato-paste`,30,`g`]]},{en:`Simmer black rice in hot fish stock and wine until tender and creamy, stirring often; this yields a dark dish without traditional squid ink.`,ua:`Готуйте чорний рис у гарячому рибному бульйоні з вином до м’якості та кремовості, регулярно помішуючи; темний колір утвориться без традиційного чорнила каракатиці.`,t:[`rice-washing`,`absorption-cooking`],m:32,i:[[`black-rice`,320,`g`],[`fish-stock`,850,`ml`],[`dry-white-wine`,110,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,40,`g`],[`parmigiano-reggiano`,55,`g`]]}];var u={slug:t,id:n,country:`HR`,region:o,servings:4,minutes:45,title:g,text:l,steps:d};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,t as slug,d as steps,l as text,g as title};